insert into public.submission_packages (id, client_id, submission_id, role_id, requirement_set_id, version, why_shared, strengths, points_to_clarify, key_facts) values
  (md5('portal-m3:package:harbor:tb-isl:1')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:tb-isl')::uuid, md5('portal-m1:role:harbor:isl')::uuid, md5('portal-m3:set:harbor:isl:1')::uuid, 1, 'Taylor has led an eight-person inside sales team at a fastener distributor for four years and runs a weekly call-review routine. Revenue Optics shared Taylor because the team-leadership and distribution experience match the role closely; CRM reporting depth is the main point to confirm.', array['Has run the same kind of team this role leads', 'Clear, structured coaching routine', 'Knows branch handoffs from the distributor side']::text[], array['Which CRM reports Taylor builds personally', 'Comfort with the hybrid schedule (three office days)']::text[], '[{"label":"Notice period","value":"4 weeks"},{"label":"Work arrangement","value":"Hybrid works; based 25 minutes from Chicago office"},{"label":"Team size led","value":"8 representatives"}]'::jsonb),
  (md5('portal-m3:package:harbor:tb-rsm:1')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:tb-rsm')::uuid, md5('portal-m1:role:harbor:rsm')::uuid, md5('portal-m3:set:harbor:rsm:1')::uuid, 1, 'Shared for the regional role because of Taylor''s distribution background and team leadership. Taylor has not managed a multi-branch region, which is the main gap.', array['Distribution experience', 'Structured coaching']::text[], array['Readiness for a regional, multi-branch scope']::text[], '[{"label":"Notice period","value":"4 weeks"},{"label":"Work arrangement","value":"Hybrid; open to regular travel to Milwaukee"}]'::jsonb),
  (md5('portal-m3:package:harbor:je-isl:1')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:je-isl')::uuid, md5('portal-m1:role:harbor:isl')::uuid, md5('portal-m3:set:harbor:isl:1')::uuid, 1, 'Jordan supervises counter and inside sales at a large electrical distributor branch and has introduced CRM dashboards for the team.', array['Hands-on CRM reporting', 'Bilingual']::text[], array['How Jordan would set up a coaching routine']::text[], '[{"label":"Notice period","value":"2 weeks"},{"label":"Work arrangement","value":"Hybrid works"}]'::jsonb),
  (md5('portal-m3:package:harbor:pr-isl:1')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:pr-isl')::uuid, md5('portal-m1:role:harbor:isl')::uuid, md5('portal-m3:set:harbor:isl:1')::uuid, 1, 'Priya leads a four-person inside sales team in packaging distribution and has strong CRM reporting experience. Team size is smaller than this role.', array['Strong reporting habits', 'Local to the Chicago office']::text[], array['Coaching approach', 'Readiness for a larger team']::text[], '[{"label":"Notice period","value":"3 weeks"},{"label":"Work arrangement","value":"Hybrid works"}]'::jsonb),
  (md5('portal-m3:package:harbor:mw-isl:1')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:mw-isl')::uuid, md5('portal-m1:role:harbor:isl')::uuid, md5('portal-m3:set:harbor:isl:1')::uuid, 1, 'Strong account management background; no team leadership yet.', array['Customer relationships']::text[], array[]::text[], '[{"label":"Notice period","value":"2 weeks"}]'::jsonb),
  (md5('portal-m3:package:harbor:en-pa:1')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:en-pa')::uuid, md5('portal-m1:role:harbor:pa')::uuid, md5('portal-m3:set:harbor:pa:1')::uuid, 1, 'Elena runs margin analysis for a 40,000-item catalogue and writes the monthly pricing memo for her commercial team.', array['Directly relevant catalogue size', 'Clear writer']::text[], array['Time-zone overlap with the Chicago team']::text[], '[{"label":"Notice period","value":"4 weeks"},{"label":"Work arrangement","value":"Remote"}]'::jsonb),
  (md5('portal-m3:package:harbor:so-pa:1')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:so-pa')::uuid, md5('portal-m1:role:harbor:pa')::uuid, md5('portal-m3:set:harbor:pa:1')::uuid, 1, 'Samuel models price changes for a manufacturer selling through distributors.', array['Modelling depth']::text[], array['Written communication']::text[], '[{"label":"Notice period","value":"2 weeks"},{"label":"Work arrangement","value":"Remote"}]'::jsonb),
  (md5('portal-m3:package:harbor:bc-pa:1')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:bc-pa')::uuid, md5('portal-m1:role:harbor:pa')::uuid, md5('portal-m3:set:harbor:pa:1')::uuid, 1, 'Strong analyst from retail; no distribution pricing.', array[]::text[], array[]::text[], '[]'::jsonb),
  (md5('portal-m3:package:harbor:gl-rsm:1')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:gl-rsm')::uuid, md5('portal-m1:role:harbor:rsm')::uuid, md5('portal-m3:set:harbor:rsm:1')::uuid, 1, 'Grace manages three branches'' field teams for a regional distributor.', array['Has done this job at a smaller scale']::text[], array[]::text[], '[{"label":"Notice period","value":"6 weeks"}]'::jsonb),
  (md5('portal-m3:package:harbor:do-rsm:1')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:do-rsm')::uuid, md5('portal-m1:role:harbor:rsm')::uuid, md5('portal-m3:set:harbor:rsm:1')::uuid, 1, 'Placed earlier in the search.', array[]::text[], array[]::text[], '[{"label":"Start date","value":"2 Nov 2026"}]'::jsonb),
  (md5('portal-m3:package:harbor:ab-fsr:1')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:ab-fsr')::uuid, md5('portal-m1:role:harbor:fsr')::uuid, md5('portal-m3:set:harbor:fsr:1')::uuid, 1, 'Aisha covers a Dallas-area territory for a hydraulics distributor and visits about 30 accounts a month.', array['Same territory', 'Technical product knowledge']::text[], array['Non-compete terms, if any']::text[], '[{"label":"Notice period","value":"2 weeks"},{"label":"Work arrangement","value":"Field-based in Dallas"}]'::jsonb),
  (md5('portal-m3:package:harbor:cm-rsm:1')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:cm-rsm')::uuid, md5('portal-m1:role:harbor:rsm')::uuid, md5('portal-m3:set:harbor:rsm:1')::uuid, 1, 'Chris manages a large branch and its field team.', array['Deep branch experience']::text[], array['Multi-branch scope']::text[], '[{"label":"Notice period","value":"4 weeks"}]'::jsonb),
  (md5('portal-m3:package:harbor:je-isl:2')::uuid, md5('portal-m1:client:harbor')::uuid, md5('portal-m1:submission:harbor:je-isl')::uuid, md5('portal-m1:role:harbor:isl')::uuid, md5('portal-m3:set:harbor:isl:1')::uuid, 2, 'Fictional draft revision (never published).', array[]::text[], array[]::text[], '[]'::jsonb),
